() => { const w = document.querySelector('#workspace'); const sel = {};
  document.querySelectorAll('#receipt [data-slot]').forEach(el => { sel[el.getAttribute('data-slot')] = el.getAttribute('data-selection-id'); });
  return {session_id: w.getAttribute('data-session-id'), stage: w.getAttribute('data-stage'),
          revision: parseInt(w.getAttribute('data-revision')), submitted: w.getAttribute('data-submitted') === 'true', selected: sel}; }
